const CACHE_MESSAGE_KEY = "whale-parasites-associates-cache-message";
const APP_CACHE_PREFIX = "whale-parasites-associates";

let currentFilter = "all";
let currentSearch = "";

document.addEventListener("DOMContentLoaded", () => {
  buildJumpMenu();
  buildFilters();
  buildCards();
  setupSearch();
  setupTroubleshooting();
  restoreUpdateMessage();
  setupClearCache();
  registerServiceWorker();
  applyCardVisibility();

  if (window.renderRelatedHubTopics) {
    window.renderRelatedHubTopics("whale-parasites-associates");
  }
});

function escapeHTML(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function normalizeText(value) {
  return String(value || "").toLowerCase().trim();
}

function buildJumpMenu() {
  const select = document.getElementById("jumpSelect");
  if (!select) return;

  PARASITES.forEach((item) => {
    const option = document.createElement("option");
    option.value = item.id;
    option.textContent = item.name;
    select.appendChild(option);
  });

  select.addEventListener("change", () => {
    const id = select.value;
    if (!id) return;

    const card = document.getElementById(id);
    if (!card) return;

    card.dataset.hidden = "false";
    card.open = true;

    setTimeout(() => {
      card.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 75);

    select.value = "";
  });
}

function buildFilters() {
  const filterTabs = document.getElementById("filterTabs");
  if (!filterTabs) return;

  filterTabs.innerHTML = FILTERS.map(([id, label], index) => `
    <button
      class="filter-tab ${index === 0 ? "active" : ""}"
      type="button"
      data-filter="${escapeHTML(id)}"
      aria-pressed="${index === 0 ? "true" : "false"}"
    >
      ${escapeHTML(label)}
    </button>
  `).join("");

  document.querySelectorAll(".filter-tab").forEach((button) => {
    button.addEventListener("click", () => {
      currentFilter = button.dataset.filter || "all";

      document.querySelectorAll(".filter-tab").forEach((tab) => {
        tab.classList.remove("active");
        tab.setAttribute("aria-pressed", "false");
      });

      button.classList.add("active");
      button.setAttribute("aria-pressed", "true");
      applyCardVisibility();
    });
  });
}

function buildCards() {
  const cardList = document.getElementById("cardList");
  if (!cardList) return;

  cardList.innerHTML = PARASITES.map((item) => {
    const paragraphs = item.paragraphs
      .map((paragraph) => `<p>${escapeHTML(paragraph)}</p>`)
      .join("");

    const hosts = item.hosts
      .map((host) => `<span class="host-chip">${escapeHTML(host)}</span>`)
      .join("");

    const dots = [1, 2, 3, 4].map((number) => {
      const filled = number <= item.harmDots ? "filled" : "";
      const warn = item.warn ? "warn" : "";
      return `<span class="dot ${filled} ${warn}" aria-hidden="true"></span>`;
    }).join("");

    const facts = item.facts
      .map(([label, value]) => `
        <span class="fact-pill">
          <strong>${escapeHTML(label)}</strong> ${escapeHTML(value)}
        </span>
      `)
      .join("");

    const searchableText = [
      item.name,
      item.sci,
      item.tag,
      item.hostsTitle,
      item.harm,
      item.paragraphs.join(" "),
      item.hosts.join(" "),
      item.facts.flat().join(" ")
    ].join(" ");

    return `
      <details
        class="card"
        id="${escapeHTML(item.id)}"
        data-category="${escapeHTML(item.categories.join(" "))}"
        data-search="${escapeHTML(normalizeText(searchableText))}"
      >
        <summary class="card-trigger">
          <div class="card-icon" style="background:${escapeHTML(item.iconBg)};" aria-hidden="true">${escapeHTML(item.icon)}</div>

          <div class="card-meta">
            <div class="card-name">${escapeHTML(item.name)}</div>
            <div class="card-sci">${escapeHTML(item.sci)}</div>
          </div>

          <span class="card-tag ${escapeHTML(item.tagClass)}">${escapeHTML(item.tag)}</span>
          <span class="card-chevron" aria-hidden="true">›</span>
        </summary>

        <div class="card-body">
          ${paragraphs}

          <div class="hosts-label">${escapeHTML(item.hostsTitle)}</div>
          <div class="host-chips">
            ${hosts}
          </div>

          <div class="harm-bar" aria-label="Harm level: ${escapeHTML(item.harm)}">
            <span class="harm-label">Harm</span>
            <div class="harm-dots">${dots}</div>
            <span>${escapeHTML(item.harm)}</span>
          </div>

          <div class="fact-row">
            ${facts}
          </div>
        </div>
      </details>
    `;
  }).join("");
}

function setupSearch() {
  const searchInput = document.getElementById("searchInput");
  if (!searchInput) return;

  searchInput.addEventListener("input", () => {
    currentSearch = normalizeText(searchInput.value);
    applyCardVisibility();
  });
}

function applyCardVisibility() {
  const cards = Array.from(document.querySelectorAll(".card"));
  const resultCount = document.getElementById("resultCount");
  let visibleCount = 0;

  cards.forEach((card) => {
    const categories = card.dataset.category || "";
    const searchableText = card.dataset.search || "";
    const matchesFilter = currentFilter === "all" || categories.split(" ").includes(currentFilter);
    const matchesSearch = !currentSearch || searchableText.includes(currentSearch);
    const shouldShow = matchesFilter && matchesSearch;

    card.dataset.hidden = shouldShow ? "false" : "true";
    if (shouldShow) visibleCount += 1;
  });

  if (resultCount) {
    if (visibleCount === cards.length && !currentSearch && currentFilter === "all") {
      resultCount.textContent = `${visibleCount} entries shown.`;
    } else {
      resultCount.textContent = `${visibleCount} matching entr${visibleCount === 1 ? "y" : "ies"} shown.`;
    }
  }
}

function setupTroubleshooting() {
  const openButton = document.getElementById("troubleshootingBtn");
  const closeButton = document.getElementById("closeTroubleshootingBtn");
  const panel = document.getElementById("troubleshootingPanel");

  if (!openButton || !closeButton || !panel) return;

  const openPanel = () => {
    panel.hidden = false;
    openButton.setAttribute("aria-expanded", "true");
    panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  };

  const closePanel = () => {
    panel.hidden = true;
    openButton.setAttribute("aria-expanded", "false");
    openButton.focus({ preventScroll: true });
  };

  openButton.addEventListener("click", () => {
    if (panel.hidden) {
      openPanel();
    } else {
      closePanel();
    }
  });

  closeButton.addEventListener("click", closePanel);

  panel.addEventListener("click", (event) => {
    if (event.target && event.target.id === "closeTroubleshootingBtn") {
      closePanel();
    }
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !panel.hidden) {
      closePanel();
    }
  });
}

function restoreUpdateMessage() {
  const updateMessage = document.getElementById("updateMessage");
  const savedMessage = localStorage.getItem(CACHE_MESSAGE_KEY);

  if (updateMessage && savedMessage) {
    updateMessage.textContent = savedMessage;
  }
}

function setupClearCache() {
  const button = document.getElementById("clearCacheBtn");
  const updateMessage = document.getElementById("updateMessage");

  if (!button || !updateMessage) return;

  button.addEventListener("click", async () => {
    const now = new Date();
    const successMessage = `Cache cleared. Last checked: ${now.toLocaleString()}`;

    updateMessage.textContent = successMessage;
    localStorage.setItem(CACHE_MESSAGE_KEY, successMessage);

    try {
      if ("caches" in window) {
        const cacheNames = await caches.keys();
        const thisAppCaches = cacheNames.filter((cacheName) =>
          cacheName.startsWith(APP_CACHE_PREFIX)
        );

        await Promise.all(thisAppCaches.map((cacheName) => caches.delete(cacheName)));
      }

      if ("serviceWorker" in navigator) {
        const registrations = await navigator.serviceWorker.getRegistrations();
        await Promise.all(
          registrations
            .filter((registration) => registration.scope.includes("whale-parasites-associates"))
            .map((registration) => registration.update())
        );
      }
    } catch (error) {
      console.warn("Cache clear warning:", error);
    }

    setTimeout(() => window.location.reload(), 700);
  });
}

function registerServiceWorker() {
  if ("serviceWorker" in navigator) {
    window.addEventListener("load", () => {
      navigator.serviceWorker.register("sw.js", { scope: "./" }).catch((error) => {
        console.warn("Service worker registration failed:", error);
      });
    });
  }
}

:root {
  --navy: #0B2A4A;
  --navy-2: #0E3A5C;
  --teal: #1A8C8C;
  --teal-light: #2AADAD;
  --foam: #EFF6F7;
  --foam-2: #F8FCFC;
  --sand: #C8A97A;
  --slate: #7EA3B0;
  --white: #FFFFFF;
  --text: #1C3245;
  --muted: #5A7A8A;
  --border: #C5DDE4;
  --danger-soft: #FFF0E8;
  --shadow: 0 10px 28px rgba(11, 42, 74, 0.12);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  background: var(--foam);
  scroll-behavior: smooth;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top right, rgba(42, 173, 173, 0.16), transparent 34rem),
    linear-gradient(180deg, #EFF6F7 0%, #F8FCFC 100%);
  color: var(--text);
  min-height: 100vh;
}

button,
input,
select {
  font: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-header {
  background:
    linear-gradient(135deg, rgba(11, 42, 74, 0.98), rgba(14, 58, 92, 0.98)),
    radial-gradient(circle at top right, rgba(42, 173, 173, 0.32), transparent 18rem);
  padding: 1rem 1.1rem 1.2rem;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 4px 22px rgba(11, 42, 74, 0.34);
}

.top-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin-bottom: 0.65rem;
}

.top-button {
  min-height: 44px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.1);
  color: var(--white);
  border-radius: 999px;
  padding: 0.58rem 0.58rem;
  font-size: 0.74rem;
  font-weight: 900;
  text-decoration: none;
  text-align: center;
  cursor: pointer;
  backdrop-filter: blur(8px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1.1;
}

.top-button:hover,
.top-button:focus-visible,
.close-panel:hover,
.close-panel:focus-visible,
.filter-tab:hover,
.filter-tab:focus-visible {
  outline: 3px solid rgba(42, 173, 173, 0.28);
  outline-offset: 2px;
}

.top-button:active {
  transform: scale(0.98);
}

.update-message {
  color: rgba(239, 246, 247, 0.86);
  font-size: 0.72rem;
  line-height: 1.35;
  margin-bottom: 0.8rem;
}

.troubleshooting-panel {
  background: rgba(255, 255, 255, 0.96);
  border: 1px solid rgba(197, 221, 228, 0.78);
  border-radius: 18px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
  color: var(--text);
  margin-bottom: 1rem;
  overflow: hidden;
}

.troubleshooting-panel[hidden] {
  display: none !important;
}

.troubleshooting-header {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.85rem;
  background: var(--foam);
  border-bottom: 1px solid var(--border);
}

.troubleshooting-header h2 {
  font-family: "Playfair Display", Georgia, serif;
  font-size: 1.2rem;
  color: var(--navy);
}

.close-panel {
  min-height: 42px;
  border: 1px solid var(--border);
  background: var(--navy);
  color: var(--white);
  border-radius: 999px;
  padding: 0.5rem 0.8rem;
  font-size: 0.78rem;
  font-weight: 900;
  cursor: pointer;
}

.troubleshooting-grid {
  display: grid;
  gap: 0.75rem;
  padding: 0.85rem;
}

.troubleshooting-grid div {
  background: var(--foam-2);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 0.8rem;
}

.troubleshooting-grid h3 {
  color: var(--navy);
  font-size: 0.9rem;
  margin-bottom: 0.28rem;
}

.troubleshooting-grid p {
  color: var(--text);
  font-size: 0.8rem;
  line-height: 1.55;
}

.header-eyebrow {
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--slate);
  margin-bottom: 0.25rem;
}

.header-title {
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(1.65rem, 7vw, 2.45rem);
  font-weight: 700;
  color: var(--white);
  line-height: 1.06;
  margin-bottom: 0.45rem;
}

.header-title span {
  color: var(--sand);
}

.header-subtitle {
  color: rgba(239, 246, 247, 0.88);
  font-size: 0.86rem;
  line-height: 1.45;
  margin-bottom: 1rem;
  max-width: 46rem;
}

.header-tools {
  display: grid;
  gap: 0.65rem;
}

.select-wrapper {
  position: relative;
}

.select-wrapper::after {
  content: "▾";
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-52%);
  color: var(--teal-light);
  pointer-events: none;
  font-size: 1.05rem;
}

select,
.search-wrapper input {
  width: 100%;
  background: rgba(255, 255, 255, 0.09);
  border: 1px solid rgba(126, 163, 176, 0.42);
  border-radius: 12px;
  color: var(--white);
  font-size: 0.92rem;
  font-weight: 700;
  outline: none;
}

select {
  appearance: none;
  padding: 0.78rem 2.7rem 0.78rem 1rem;
}

.search-wrapper input {
  min-height: 44px;
  padding: 0.78rem 1rem;
}

.search-wrapper input::placeholder {
  color: rgba(239, 246, 247, 0.68);
}

select:focus,
.search-wrapper input:focus {
  border-color: var(--teal-light);
  box-shadow: 0 0 0 3px rgba(42, 173, 173, 0.18);
}

select option {
  background: var(--navy);
  color: var(--white);
}

main {
  width: min(100%, 780px);
  margin: 0 auto;
  padding: 1.05rem;
}

.naturalist-note,
.quick-guide,
.card,
.references-section,
.related-hub-topics {
  box-shadow: var(--shadow);
}

.naturalist-note {
  background: linear-gradient(135deg, var(--navy), var(--navy-2));
  border: 1px solid rgba(126, 163, 176, 0.28);
  border-radius: 18px;
  padding: 1.05rem;
  margin-bottom: 0.85rem;
}

.note-eye {
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--sand);
  margin-bottom: 0.45rem;
}

.naturalist-note p {
  font-size: 0.88rem;
  line-height: 1.65;
  color: rgba(239, 246, 247, 0.92);
}

.quick-guide,
.references-section,
.related-hub-topics {
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 1rem;
  margin-bottom: 0.85rem;
}

.quick-guide h2,
.references-section h2,
.related-hub-topics h2 {
  font-family: "Playfair Display", Georgia, serif;
  color: var(--navy);
  font-size: 1.18rem;
  margin-bottom: 0.75rem;
}

.references-section p,
.related-hub-topics p {
  font-size: 0.84rem;
  line-height: 1.6;
  color: var(--text);
  margin-top: 0.45rem;
}

.quick-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
}

.quick-grid div {
  background: var(--foam);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0.7rem;
}

.quick-grid strong {
  display: block;
  color: var(--navy);
  font-size: 0.8rem;
  margin-bottom: 0.18rem;
}

.quick-grid span {
  display: block;
  color: var(--muted);
  font-size: 0.74rem;
  line-height: 1.3;
}

.filter-tabs {
  display: flex;
  gap: 0.45rem;
  margin: 0.95rem 0 0.45rem;
  overflow-x: auto;
  padding-bottom: 0.25rem;
  scrollbar-width: none;
}

.filter-tabs::-webkit-scrollbar {
  display: none;
}

.filter-tab {
  white-space: nowrap;
  min-height: 38px;
  font-size: 0.74rem;
  font-weight: 900;
  letter-spacing: 0.02em;
  padding: 0.48rem 0.86rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--white);
  color: var(--muted);
  cursor: pointer;
}

.filter-tab.active {
  background: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}

.result-count {
  font-size: 0.76rem;
  font-weight: 800;
  color: var(--muted);
  margin: 0 0 0.8rem 0.1rem;
}

.card-list {
  display: grid;
  gap: 0.82rem;
}

.card {
  background: rgba(255, 255, 255, 0.96);
  border-radius: 18px;
  border: 1px solid var(--border);
  overflow: hidden;
}

.card[data-hidden="true"] {
  display: none;
}

.card-trigger {
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
  cursor: pointer;
  list-style: none;
}

.card-trigger::-webkit-details-marker {
  display: none;
}

.card-icon {
  width: 2.9rem;
  height: 2.9rem;
  border-radius: 16px;
  display: grid;
  place-items: center;
  font-size: 1.42rem;
  flex-shrink: 0;
}

.card-meta {
  min-width: 0;
}

.card-name {
  font-family: "Playfair Display", Georgia, serif;
  font-size: 1.16rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.15;
}

.card-sci {
  font-size: 0.76rem;
  font-style: italic;
  color: var(--muted);
  margin-top: 0.18rem;
}

.card-tag {
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.26rem 0.56rem;
  border-radius: 999px;
  text-align: center;
}

.tag-broad { background: #E8F4F0; color: #2A7A5A; }
.tag-whale { background: #E8EFF8; color: #2A4A8A; }
.tag-specific { background: #F4EBE0; color: #8A4A1A; }
.tag-mutualist { background: #EBF4F4; color: #1A6A6A; }

.card-chevron {
  color: var(--teal);
  font-size: 1.35rem;
  line-height: 1;
  transition: transform 0.25s ease;
}

details[open] .card-chevron {
  transform: rotate(90deg);
}

.card-body {
  border-top: 1px solid var(--border);
  padding: 0.05rem 1rem 1.05rem;
}

.card-body p {
  font-size: 0.92rem;
  line-height: 1.68;
  color: var(--text);
  margin-top: 0.9rem;
}

.hosts-label {
  font-size: 0.65rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 1rem;
  margin-bottom: 0.48rem;
}

.host-chips,
.fact-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.host-chip {
  font-size: 0.74rem;
  background: var(--navy);
  color: var(--foam);
  border-radius: 999px;
  padding: 0.28rem 0.72rem;
}

.harm-bar {
  display: grid;
  grid-template-columns: auto auto 1fr;
  align-items: center;
  gap: 0.58rem;
  margin-top: 0.95rem;
  font-size: 0.76rem;
  color: var(--muted);
}

.harm-label {
  font-weight: 900;
  color: var(--navy);
}

.harm-dots {
  display: flex;
  gap: 3px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--border);
}

.dot.filled {
  background: var(--teal);
}

.dot.filled.warn {
  background: var(--sand);
}

.fact-row {
  margin-top: 0.9rem;
}

.fact-pill {
  font-size: 0.72rem;
  font-weight: 700;
  background: var(--foam-2);
  border: 1px solid var(--border);
  border-radius: 9px;
  padding: 0.38rem 0.66rem;
  color: var(--navy);
}

.fact-pill strong {
  color: var(--teal);
  font-weight: 900;
}

footer {
  text-align: center;
  padding: 2rem 1rem 3rem;
  font-size: 0.72rem;
  color: var(--muted);
  line-height: 1.55;
}

@media (max-width: 380px) {
  .top-actions {
    grid-template-columns: 1fr;
  }

  .top-button {
    width: 100%;
  }
}

@media (max-width: 520px) {
  .card-trigger {
    grid-template-columns: auto 1fr auto;
  }

  .card-tag {
    grid-column: 2 / 4;
    justify-self: start;
  }
}

@media (min-width: 720px) {
  .app-header {
    padding: 1.15rem 2rem 1.35rem;
  }

  .top-actions {
    max-width: 30rem;
  }

  .header-tools {
    grid-template-columns: 1fr 1fr;
  }

  main {
    padding: 1.35rem;
  }

  .naturalist-note,
  .quick-guide,
  .card-body,
  .references-section,
  .related-hub-topics {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }

  .troubleshooting-grid {
    grid-template-columns: 1fr 1fr;
  }

  .card-trigger {
    padding: 1.1rem 1.25rem;
  }

  .quick-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;const u=new URL(e.request.url);if(u.origin!==self.location.origin||!u.pathname.startsWith("/MBA-hub/"))return;e.stopImmediatePropagation();e.respondWith((async()=>{const c=await caches.open("mba-shared-assets-v1");const key=e.request.mode==="navigate"&&u.pathname.endsWith("/")?new URL("index.html",u.href).href:u.href;const hit=await c.match(key,{ignoreSearch:true})||await c.match(e.request,{ignoreSearch:true});if(hit)return hit;const local=await caches.open(CACHE_NAME);const old=await local.match(e.request,{ignoreSearch:true});if(old)return old;try{return await fetch(e.request)}catch(err){return Response.error()}})())});
const CACHE_NAME = "whale-parasites-associates-v5";

const FILES_TO_CACHE = [
  "./",
  "./index.html",
  "./styles.css",
  "./app.js",
  "./data.js",
  "./manifest.json",
  "./images/icon.svg",
  "../../apps.js",
  "../../hub-links.js"
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(FILES_TO_CACHE))
  );

  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) =>
      Promise.all(
        cacheNames.map((cacheName) => {
          if (
            cacheName !== CACHE_NAME &&
            cacheName.startsWith("whale-parasites-associates")
          ) {
            return caches.delete(cacheName);
          }

          return null;
        })
      )
    )
  );

  self.clients.claim();
});
